package wordcount

import (
	"reflect"
	"testing"
)

func TestWordCount(t *testing.T) {
	tests := []struct {
		name, input string
		want        map[string]int
	}{
		{
			name:  "empty string",
			input: "",
			want:  map[string]int{},
		},
		{
			name:  "single word",
			input: "hello",
			want:  map[string]int{"hello": 1},
		},
		{
			name:  "mixed case",
			input: "Go go GO",
			want:  map[string]int{"go": 3},
		},
		{
			name:  "punctuation",
			input: "Hello, world! How are you?",
			want: map[string]int{
				"hello": 1,
				"world": 1,
				"how":   1,
				"are":   1,
				"you":   1,
			},
		},
		{
			name:  "repeated words",
			input: "one two one three two one",
			want: map[string]int{
				"one":   3,
				"two":   2,
				"three": 1,
			},
		},
		{
			name:  "multi-word sentence",
			input: "The quick brown fox jumps over the lazy dog",
			want: map[string]int{
				"the":   2,
				"quick": 1,
				"brown": 1,
				"fox":   1,
				"jumps": 1,
				"over":  1,
				"lazy":  1,
				"dog":   1,
			},
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got := WordCount(tc.input)
			if !reflect.DeepEqual(got, tc.want) {
				t.Errorf("WordCount(%q) = %v; want %v", tc.input, got, tc.want)
			}
		})
	}
}

func BenchmarkWordCount(b *testing.B) {
	const input = "The quick brown fox jumps over the lazy dog, while another fox watches from the quiet forest."

	for i := 0; i < b.N; i++ {
		WordCount(input)
	}
}
